def _build_datetime(parts):
    weekdate = parts.get("weekdate")
    if weekdate is not None:
        year, week, _day = int(weekdate[0]), int(weekdate[1]), int(weekdate[2] or 1)
        dt = datetime.strptime(f"{year}-{week}-{_day}", "%G-%V-%u")
        parts.update(year=dt.year, month=dt.month, day=dt.day)
    timestamp = parts.get("timestamp")
    if timestamp is not None:
        return datetime.fromtimestamp(timestamp, tz=tz.tzutc())
    expanded_timestamp = parts.get("expanded_timestamp")
    if expanded_timestamp is not None:
        return datetime.fromtimestamp(normalize_timestamp(expanded_timestamp), tz=tz.tzutc())
    day_of_year = parts.get("day_of_year")
    if day_of_year is not None:
        _year = parts.get("year")
        month = parts.get("month")
        if _year is None:
            raise ParserError("Year component is required with the DDD and DDDD tokens.")
        if month is not None:
            raise ParserError("Month component is not allowed with the DDD and DDDD tokens.")
        try:
            dt = datetime.strptime(f"{_year}-{day_of_year}", "%Y-%j")
        except ValueError:
            raise ParserError(f"The provided day of year {day_of_year!r} is invalid.")
        parts.update(year=dt.year, month=dt.month, day=dt.day)
    day_of_week, day = parts.get("day_of_week"), parts.get("day")
    if day_of_week is not None and day is None:
        year, month = parts.get("year", 1970), parts.get("month", 1)
        next_weekday_dt = next_weekday(datetime(year, month, 1), day_of_week)
        parts.update(year=next_weekday_dt.year, month=next_weekday_dt.month, day=next_weekday_dt.day)
    am_pm, hour = parts.get("am_pm"), parts.get("hour", 0)
    if am_pm == "pm" and hour < 12:
        hour += 12
    elif am_pm == "am" and hour == 12:
        hour = 0
    if hour == 24:
        if any(parts.get(k) for k in ["minute", "second", "microsecond"]):
            raise ParserError("Midnight at the end of day must not contain minutes, seconds, or microseconds")
        hour, day_increment = 0, 1
    else:
        day_increment = 0
